import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { HostAPI } from '../dist/index.js';
import { WindowAPI, windowDTOValidators } from '../dist/window.js';

// Generated by HostWindowUsageTests from isolated synthetic Swift model owners.
const fixtures = JSON.parse(readFileSync(new URL('../fixtures/window-usage.json', import.meta.url)));
function client(results) {
  const calls = [];
  const host = new HostAPI({
    async send(request) {
      calls.push(request);
      return { version: 1, id: request.id, result: structuredClone(results[request.method]) };
    },
    subscribe() { return () => {}; }, dispose() {},
  });
  return { api: new WindowAPI(host), calls, host };
}

test('window SDK accepts real Swift DTOs across all statistics routes', async () => {
  const { api, host } = client(fixtures);
  try {
    await api.usageOverview({});
    await api.conversationsList({});
    await api.conversationDetail('fixture');
    await api.projectsList({});
    await api.projectDetail({});
    await api.quotaAnalytics({});
    await api.usageRefresh();
  } finally { api.dispose(); host.dispose(); }
});

test('window DTO validation rejects extra credential fields and invalid money', () => {
  const dto = structuredClone(fixtures['conversations.detail']);
  assert.throws(() => windowDTOValidators.conversationDetail.parse({ ...dto, accessToken: 'fixture-only' }), { code: 'invalid_response' });
  const overview = structuredClone(fixtures['window.usage.overview']);
  overview.totals.costUSD = '$12.00';
  assert.throws(() => windowDTOValidators.usageOverview.parse(overview), { code: 'invalid_response' });
});

test('pricing display strings accept formatted currency while source prices stay decimal', () => {
  const usage = fixtures['usage.refresh'];
  const price = { input: '1.25', output: '2.5', cacheRead: '0.1', cacheCreation: '0' };
  const displayPrice = { input: '¥8.75', output: '¥17.50', cacheRead: '¥0.70', cacheCreation: '¥0.00' };
  const dto = { providers: [{ id: 'fixture', name: 'Fixture', models: [{ id: 'fixture', name: 'Fixture', price, displayPrice }] }], fetchedAt: null, refreshFailed: false, usage };
  assert.deepEqual(windowDTOValidators.pricingCatalog.parse(dto), dto);
});

test('optional fields are omitted and disposed windows cannot dispatch', async () => {
  const { api, host, calls } = client(fixtures);
  try {
    await api.conversationDetail('fixture', undefined);
    assert.deepEqual(calls[0].params, { id: 'fixture' });
    api.dispose();
    await assert.rejects(api.projectsList({}), { code: 'disposed' });
    assert.equal(calls.length, 1);
  } finally { host.dispose(); }
});

test('account and settings projections from Swift match the window contract', () => {
  for (const [file, validator] of [['window-settings.json', 'settings'], ['window-accounts.json', 'quotaAccounts']]) {
    const dto = JSON.parse(readFileSync(new URL('../fixtures/' + file, import.meta.url)));
    assert.deepEqual(windowDTOValidators[validator].parse(dto), dto);
  }
});

test('dashboard routes validate DTOs and forward filters', async () => {
  const totals = fixtures['window.usage.overview'].totals;
  const status = fixtures['usage.refresh'];
  const coverage = { precision: 'day', incomplete: true, refreshing: true, unlocatedTotals: totals, message: null };
  const dashboard = { kpiDisplay: { cost: '$0', requests: '0', tokens: '0', cacheHitRate: '0%' }, revision: '1', resolvedRange: { from: '2026-01-01T00:00:00Z', to: '2026-01-02T00:00:00Z', timeZone: 'UTC', granularity: 'hour', asOf: '2026-01-02T00:00:00Z' }, coverage, totals, facets: { services: [], sources: [], models: [] }, providerRows: [], modelRows: [], samples: [], axisTicks: [], status };
  const results = { 'window.usage.dashboard': dashboard, 'window.usage.requests': { revision: '1', resolvedRange: dashboard.resolvedRange, totalCount: 0, rows: [], nextCursor: null, coverage, status }, 'window.usage.heatmap': { fromDay: '2025-01-01', toDay: '2026-01-01', timeZone: 'UTC', days: [], totals, nextBeforeDay: null, coverage, status } };
  const { api, host, calls } = client(results);
  try {
    const query = { range: 'today', metric: 'cost', service: 'codex' };
    assert.deepEqual(await api.usageDashboard(query), dashboard);
    await api.usageRequests({ ...query, limit: 20 });
    await api.usageHeatmap(query);
    assert.equal(calls[1].params.limit, 20);
    assert.throws(() => windowDTOValidators.usageDashboard.parse({ ...dashboard, credential: 'secret' }), { code: 'invalid_response' });
    const { refreshing, ...missingRefreshing } = coverage;
    assert.throws(() => windowDTOValidators.usageDashboard.parse({ ...dashboard, coverage: missingRefreshing }), { code: 'invalid_response' });
  } finally { api.dispose(); host.dispose(); }
});

test('bootstrap requires visible usage services and validates each service', () => {
  const dto = { route: { page: 'stats' }, language: 'system', resolvedLanguage: 'en', platform: 'macos', timeZone: 'UTC', appearance: 'light', version: 'test', sidebarApplications: [], visibleUsageServices: ['codex', 'claude'], capabilities: [] };
  assert.deepEqual(windowDTOValidators.bootstrap.parse(dto), dto);
  const { visibleUsageServices, ...missing } = dto;
  assert.throws(() => windowDTOValidators.bootstrap.parse(missing), { code: 'invalid_response' });
  assert.throws(() => windowDTOValidators.bootstrap.parse({ ...dto, visibleUsageServices: ['unknown'] }), { code: 'invalid_response' });
});
